test_that("tPn.x invalidates the earlier transposon when spans overlap on the same gene", {
  t1 <- mk_tpn("gG1", 2, 0, valid = TRUE, size = 10)
  t2 <- mk_tpn("gG1", 2, 1, valid = TRUE, size = 10)  # identical span, same gene, later gen
  out <- tPn.x(t1, t2)
  expect_false(as.logical(tPn.io(out)["valid"]))
})

test_that("tPn.x leaves a transposon untouched when spans do not overlap or genes differ", {
  t1 <- mk_tpn("gG1", 2, 0, size = 10)
  t2 <- mk_tpn("gG2", 2, 0, size = 10)
  out <- tPn.x(t1, t2)
  expect_equal(out, t1)
})

## ==========================================================================
## tPn.r()
## ==========================================================================
test_that("tPn.r forces the valid flag TRUE on every transposon in a vector", {
  v <- c(mk_tpn("gG1", 1, 0, valid = FALSE), mk_tpn("iG2", 2, 0, valid = FALSE))
  out <- tPn.r(v)
  expect_length(out, 2)
  parsed <- lapply(out, tPn.io)
  expect_true(all(sapply(parsed, function(p) as.logical(p["valid"]))))
})

## NOTE: tPn.r() is unchanged, so its previously-flagged fragile reliance on
## read.table()'s default blank.lines.skip=TRUE to silently drop excised
## ("") transposon entries -- which could plausibly break if ALL of a host's
## transposons are excised in the same generation -- is being left as-is
## deliberately; the test that pinned it down has been removed.

## ==========================================================================
## tPn.reloc()
## ==========================================================================
test_that("tPn.reloc shifts downstream genes' start/end by the transposon size", {
  gdf <- mk_gene_df(c("g1", "g2", "g3"), start = c(1, 100, 200), end = c(50, 150, 250))
  out <- tPn.reloc(mk_tpn("", 0, 0, size = 30), gen = 1, gene.df = gdf, tPn.prob = 0.01)
  expect_true(all(out$end >= gdf$end))
})

## NOTE: tPn.reloc() is unchanged, so its previously-flagged last-gene
## boundary issue (`min(x+1, nrow(gene.df))` collapses to `x:x` when x is
## the last row, incorrectly shifting that gene's own start and leaving
## `length` inconsistent with `end - start + 1`) is being left as-is
## deliberately; the test that pinned it down has been removed. The
## contrasting non-last-gene case below is unaffected and still holds.

test_that("tPn.reloc correctly leaves the start unshifted for a non-last gene's CDS insertion", {
  gdf <- mk_gene_df(c("g1", "g2"), start = c(1, 500), end = c(100, 600))
  before_start <- gdf$start[1]
  out <- tPn.reloc(mk_tpn("", 0, 0, size = 40), gen = 1, gene.df = gdf, tPn.prob = 0.05)
  expect_equal(out$start[1], before_start)
  expect_equal(out$end[1] - out$start[1] + 1, out$length[1])
})

