## gene.recom()
## ==========================================================================
test_that("gene.recom returns the recipient's transposon string unchanged when neither host has one at this locus", {
  out <- gene.recom("", "", g2to1 = 1, locusTags = c("g1", "g2"))
  expect_equal(out, "")
})

test_that("gene.recom transfers the donor's transposon at the target locus", {
  donor_tpn <- mk_tpn("gg2", 1, 0)
  out <- gene.recom("", donor_tpn, g2to1 = 2, locusTags = c("g1", "g2"))
  expect_equal(out, donor_tpn)
})

test_that("gene.recom's removal now uses the same 'g'-prefixed pattern as its detection check", {
  ## RESOLVED: both grep() calls in the removal steps now match
  ## paste0("g", locusTags[g2to1]) -- the SAME pattern the presence checks
  ## use -- instead of the bare tag. Previously the bare-tag removal pattern
  ## also matched an "i<tag>" (intergenic) entry at the same locus even when
  ## the presence check only looked for a "g" (coding-region) hit. Reproduced
  ## with a recipient carrying ONLY an intergenic transposon at this locus
  ## (so the outer check finds no "g" hit) alongside one at another locus
  ## that must survive untouched.
  h1 <- paste(mk_tpn("ig2", 1, 0), mk_tpn("gg9", 1, 0), sep = ";")
  out <- gene.recom(h1, "", g2to1 = 2, locusTags = c("g1", "g2", "g9"))
  expect_equal(out, h1)
})

## ==========================================================================
## g.Recom()
## ==========================================================================
test_that("g.Recom leaves the population size and column structure unchanged", {
  ## g.Recom() indexes host strings as flat CHARACTER VECTORS via
  ## strsplit(host[i], "") with a "+1" offset for haplotype-1 gene indices --
  ## that offset only makes sense if position (nGene+1) is the literal ";"
  ## separator, i.e. host must be "XXXX;YYYY" (2*nGene + 1 characters), not
  ## a bare nGene-character string.
  set.seed(13)
  h <- ini.host(4, in_file$gene, 2)
  pool <- data.frame(
    host = paste(h, h, sep = ";"),
    transposon = rep("", 4),
    familyTree = paste(1:4, 1:4, sep = ";"),
    stringsAsFactors = FALSE
  )
  ## recomRate chosen so floor(recomRate * nrow(gene.df)) >= 1, i.e. the
  ## recombination branch is actually exercised rather than a no-op
  ## (nrow(in_file$gene) == 8 here, so 0.3 * 8 = 2.4 -> floor 2).
  out <- g.Recom(pool, gene.df = in_file$gene, recomRate = 0.3, hypothesis = "switch")
  expect_equal(dim(out), dim(pool))
  expect_equal(colnames(out), colnames(pool))
})

